import java.awt.Component;
import java.awt.Container;
import javax.swing.JTabbedPane;
import javax.swing.JTextArea;

public class TabbedNotesTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Component find(Container root, String name) {
        for (Component c : root.getComponents()) {
            if (name.equals(c.getName())) {
                return c;
            }
            if (c instanceof Container) {
                Component found = find((Container) c, name);
                if (found != null) {
                    return found;
                }
            }
        }
        return null;
    }

    public static void main(String[] args) {
        try {
            TabbedNotes notes = new TabbedNotes();
            Component c = find(notes, "tabs");
            JTabbedPane pane = c instanceof JTabbedPane ? (JTabbedPane) c : null;

            check("a JTabbedPane named tabs exists", true, pane != null);
            check("no tabs to start with", 0, notes.tabCount());

            notes.addNote("Shopping", "milk");
            notes.addNote("Ideas", "write a game");

            check("tabCount after two notes", 2, notes.tabCount());
            check("the pane itself holds the tabs", 2, pane == null ? null : pane.getTabCount());
            check("titles", "Shopping|Ideas", notes.titleAt(0) + "|" + notes.titleAt(1));
            check("bodies", "milk|write a game", notes.bodyAt(0) + "|" + notes.bodyAt(1));

            Component tabComponent = pane == null || pane.getTabCount() == 0
                    ? null : pane.getComponentAt(0);
            check("each tab holds a JTextArea", true, tabComponent instanceof JTextArea);

            check("out of range index", "null null", notes.titleAt(5) + " " + notes.bodyAt(-1));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

