import javax.swing.JPanel;
import javax.swing.JTabbedPane;
import javax.swing.JTextArea;

public class TabbedNotes extends JPanel {

    private final JTabbedPane tabs = new JTabbedPane();

    public TabbedNotes() {
        tabs.setName("tabs");
        add(tabs);
    }

    public void addNote(String title, String body) {
        JTextArea area = new JTextArea(body);
        tabs.addTab(title, area);
    }

    public int tabCount() {
        return tabs.getTabCount();
    }

    public String titleAt(int index) {
        if (index < 0 || index >= tabs.getTabCount()) {
            return null;
        }
        return tabs.getTitleAt(index);
    }

    public String bodyAt(int index) {
        if (index < 0 || index >= tabs.getTabCount()) {
            return null;
        }
        return ((JTextArea) tabs.getComponentAt(index)).getText();
    }
}
